#include "contentFilter.h"

#include "contentFilterTerms.h" // generated by CMake from functions/restricted_terms.json

#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QSet>
#include <QStringList>

namespace ContentFilter {

namespace {

// Mirrors functions/main.py's _normalize() — keep both identical, or the
// shared term list will match differently on each side.
QStringList normalizedTokens(const QString& text) {
    const QString decomposed = text.normalized(QString::NormalizationForm_KD);
    QString folded;
    folded.reserve(decomposed.size());
    for (const QChar c : decomposed) {
        if (c.category() == QChar::Mark_NonSpacing)
            continue;
        folded.append(c);
    }
    folded = folded.toCaseFolded();
    folded.replace(QChar(0x00DF), QLatin1String("ss")); // ß — Qt's simple case folding keeps it

    QStringList tokens;
    QString current;
    for (QChar c : std::as_const(folded)) {
        switch (c.unicode()) {
        case '0': c = QLatin1Char('o'); break;
        case '1': c = QLatin1Char('i'); break;
        case '3': c = QLatin1Char('e'); break;
        case '4': case '@': c = QLatin1Char('a'); break;
        case '5': case '$': c = QLatin1Char('s'); break;
        default: break;
        }
        if (c.isLetterOrNumber()) {
            current.append(c);
        } else if (!current.isEmpty()) {
            tokens.append(current);
            current.clear();
        }
    }
    if (!current.isEmpty())
        tokens.append(current);
    return tokens;
}

struct Terms {
    QSet<QString> words;
    QSet<QString> imageOnlyWords;
    QStringList phrases; // normalized, space-joined, space-padded: " sex toy "
    QStringList stems;
};

const Terms& terms() {
    static const Terms t = [] {
        Terms result;
        const auto root = QJsonDocument::fromJson(QByteArray(kRestrictedTermsJson)).object();
        auto addWords = [&root](const QString& key, QSet<QString>& into) {
            for (const auto& v : root[key].toArray())
                for (const auto& token : normalizedTokens(v.toString()))
                    into.insert(token);
        };
        addWords(QStringLiteral("words"), result.words);
        addWords(QStringLiteral("image_only_words"), result.imageOnlyWords);
        for (const auto& v : root[QStringLiteral("phrases")].toArray()) {
            const QStringList tokens = normalizedTokens(v.toString());
            if (!tokens.isEmpty())
                result.phrases.append(QLatin1Char(' ') + tokens.join(QLatin1Char(' ')) + QLatin1Char(' '));
        }
        for (const auto& v : root[QStringLiteral("stems")].toArray()) {
            const QString stem = normalizedTokens(v.toString()).join(QString());
            if (!stem.isEmpty())
                result.stems.append(stem);
        }
        Q_ASSERT_X(!result.words.isEmpty(), "ContentFilter", "restricted_terms.json failed to parse");
        return result;
    }();
    return t;
}

}

bool containsRestrictedTerm(const QString& text, Scope scope) {
    const QStringList tokens = normalizedTokens(text);
    if (tokens.isEmpty())
        return false;
    const Terms& t = terms();

    for (const auto& token : tokens) {
        if (t.words.contains(token))
            return true;
        if (scope == Scope::ImageQuery && t.imageOnlyWords.contains(token))
            return true;
    }

    const QString joined = QLatin1Char(' ') + tokens.join(QLatin1Char(' ')) + QLatin1Char(' ');
    for (const auto& phrase : t.phrases)
        if (joined.contains(phrase))
            return true;
    for (const auto& stem : t.stems)
        if (joined.contains(stem))
            return true;
    return false;
}

}
